class Solution:
    def sumK(self, root, k):
        def dfs(node, target, prefix_sum_count):
            if not node:
                return 0

            current_sum = prefix_sum_count.get(target - node.val, 0)

            prefix_sum_count[node.val] = prefix_sum_count.get(node.val, 0) + 1

            left_count = dfs(node.left, target, prefix_sum_count)
            right_count = dfs(node.right, target, prefix_sum_count)

            prefix_sum_count[node.val] -= 1

            return current_sum + left_count + right_count

        return dfs(root, k, {0: 1}) % (10**9 + 7)
